#include <cstdlib>
#include <string>

int migrate_database(const std::string& db_name, const std::string& migration_file) {
    std::string cmd = "psql -d " + db_name + " -f " + migration_file;
    return system(cmd.c_str());
}

int seed_data(const std::string& env) {
    std::string cmd = "python seed.py --env=" + env;
    return system(cmd.c_str());
}
